+    {
+      bk7258_boottrace_detail(3, 1);
+    }
+
+  nxsched_process_timer();
+
+  if (bk7258_boottrace_primary_stage() == BK7258_BOOT_CPU2_FIRST_IRQ)
+    {
+      bk7258_boottrace_detail(3, 2);
+    }
+
+  return OK;
+}
+
+void bk7258_timer_start(void)
+{
+  DEBUGASSERT(up_cpu_index() == 0);
+
+  putreg32(0, NVIC_SYSTICK_CURRENT);
+  bk7258_boottrace_primary(BK7258_BOOT_SYSTICK_STARTED);
+  putreg32(NVIC_SYSTICK_CTRL_CLKSOURCE | NVIC_SYSTICK_CTRL_TICKINT |
+           NVIC_SYSTICK_CTRL_ENABLE, NVIC_SYSTICK_CTRL);
+  up_enable_irq(BK7258_IRQ_SYSTICK);
